/// Where shipments rows are kept. Services depend only on this protocol.
public protocol ShipmentRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: String) async throws -> Shipment?

    /// At most limit rows from offset, by primary key, and how many there are.
    func list(offset: Int, limit: Int) async throws -> Page<Shipment>

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Shipment) async throws -> Shipment

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Shipment) async throws -> Shipment

    /// Removes a row.
    func delete(_ entity: Shipment) async throws

    /// Adds an item to stops, and gives the row as it is then, if there is one.
    func addStop(_ id: String, _ stop: Shipment.Stop) async throws -> Shipment?

    /// Removes an item from stops that has this size, and gives the row as it is then, if there is one.
    func removeStop(_ id: String, _ position: Int, _ size: Int) async throws -> Shipment?
}

/// Keeps shipments rows in the database, through MongoKitten: on the database of the unit of work, or on its transaction.
public struct MongoShipmentRepository: ShipmentRepository {
    let database: Db

    public init(db: Db) {
        self.database = db
    }

    public func findById(_ id: String) async throws -> Shipment? {
        guard Bson.isObjectId(id) else { return nil }
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await database.find("shipments", documentFilter, limit: 1).first.map(Shipment.from)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<Shipment> {
        let documentFilter: BsonDocument = [:]
        let total = try await database.count("shipments", documentFilter)
        let found = limit > 0 ? try await database.find("shipments", documentFilter, sort: ["_id": 1], skip: offset, limit: limit) : []
        return Page(items: try found.map(Shipment.from), total: total, offset: offset, limit: limit)
    }

    @discardableResult
    public func insert(_ entity: Shipment) async throws -> Shipment {
        var entity = entity
        entity.id = entity.id ?? Bson.newId()
        let document = try entity.toDocument()
        try await write { try await database.insert("shipments", document) }
        entity.loadedDocument = Loaded(document: document)
        return entity
    }

    @discardableResult
    public func update(_ entity: Shipment) async throws -> Shipment {
        var entity = entity
        let now = try entity.toDocument()
        let fields = ["parcel", "stops"]
        let changes = Bson.changes(entity.loadedDocument.document, now, fields)
        if !changes.isEmpty, let id = now["_id"] {
            try await write { try await database.update("shipments", ["_id": id], changes) }
        }
        entity.loadedDocument = Loaded(document: now)
        return entity
    }

    public func delete(_ entity: Shipment) async throws {
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(entity.id!)]
        try await write { try await database.delete("shipments", documentFilter) }
    }

    public func addStop(_ id: String, _ stop: Shipment.Stop) async throws -> Shipment? {
        guard Bson.isObjectId(id) else { return nil }
        let change: BsonDocument = ["$push": ["stops": try Bson.ofNested(stop)] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id)]
        return try await write { try await database.change("shipments", documentFilter, change) }.map(Shipment.from)
    }

    public func removeStop(_ id: String, _ position: Int, _ size: Int) async throws -> Shipment? {
        guard Bson.isObjectId(id) else { return nil }
        let head: BsonDocument = ["$slice": ["$stops", position] as BsonDocument]
        let tail: BsonDocument = ["$slice": ["$stops", position + 1, max(size, 1)] as BsonDocument]
        let set: BsonDocument = ["stops": ["$concatArrays": [head, tail] as BsonDocument] as BsonDocument]
        let change: BsonDocument = [["$set": set] as BsonDocument]
        let documentFilter: BsonDocument = ["_id": try Bson.ofObjectId(id), "stops": ["$size": size] as BsonDocument]
        return try await write { try await database.change("shipments", documentFilter, change) }.map(Shipment.from)
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error where isRefusal(error) {
            throw DomainError.conflict(entity: "Shipment", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

