/// Operations on customers. Repositories commit every write.
public struct CustomerService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Customer after checking it.
    @discardableResult
    public func createCustomer(_ data: CustomerCreate) async throws -> CustomerRead {
        let values = Values(email: data.email.map(Optional.some), level: data.level.map(Optional.some), since: data.since.map(Optional.some), address: data.address.map(Optional.some), tags: data.tags.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Customer()
            applyValues(&entity, values)
            return try await read(uow.customers.insert(entity))
        }
    }

    /// The Customer with this key; notFound when there is none.
    public func getCustomer(_ id: String) async throws -> CustomerRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of customers, by primary key.
    public func listCustomers(offset: Int, limit: Int) async throws -> Page<CustomerRead> {
        try await unitOfWork.customers.list(offset: offset, limit: limit).map(read)
    }

    /// Changes the given values of a Customer.
    @discardableResult
    public func updateCustomer(_ id: String, _ changes: CustomerUpdate) async throws -> CustomerRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.customers.update(current))
        }
    }

    /// Deletes a Customer.
    public func deleteCustomer(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.customers.delete(current)
        }
    }

    /// The Customer with this email, or nil.
    public func findCustomerByEmail(_ email: String) async throws -> CustomerRead? {
        try await unitOfWork.customers.findByEmail(email).map(read)
    }

    /// Adds an item to tags.
    @discardableResult
    public func addTag(_ id: String, _ tag: String) async throws -> CustomerRead {
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.customers.addTag(id, tag) else {
                throw DomainError.notFound(entity: "Customer", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from tags, by its value.
    @discardableResult
    public func removeTag(_ id: String, _ tag: String) async throws -> CustomerRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.tags ?? []).contains(tag) {
                throw DomainError.notFound(entity: "Tag", key: "\(tag)")
            }
            guard let changed = try await uow.customers.removeTag(id, tag) else {
                throw DomainError.notFound(entity: "Customer", key: "\(id)")
            }
            return read(changed)
        }
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var email: String?? = nil
    var level: String?? = nil
    var since: Date?? = nil
    var address: Customer.Address?? = nil
    var tags: [String]?? = nil
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if values.email ?? nil == nil && (creating || values.email != nil) {
        errors.append(FieldError("email", "is required"))
    }
    if let value = values.level ?? nil {
        if !["basic", "gold"].contains(value) {
            errors.append(FieldError("level", "must be one of: basic, gold"))
        }
    }
    if values.since ?? nil == nil && (creating || values.since != nil) {
        errors.append(FieldError("since", "is required"))
    }
    if let value = values.address ?? nil {
        checkCustomerAddress(value, "address", &errors)
    } else if creating || values.address != nil {
        errors.append(FieldError("address", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Customer", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    if let email = values.email ?? current?.email,
       let other = try await uow.customers.findByEmail(email),
       current.map({ other.id != $0.id }) ?? true {
        throw DomainError.conflict(entity: "Customer", reason: "email is already taken", fields: ["email"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Customer, _ values: Values) {
    if let value = values.email { entity.email = value }
    if let value = values.level { entity.level = value }
    if let value = values.since { entity.since = value }
    if let value = values.address { entity.address = value }
    if let value = values.tags { entity.tags = value }
}

/// What a Customer.Address does not follow of its rules, each with the path of its field.
fileprivate func checkCustomerAddress(_ value: Customer.Address, _ path: String, _ errors: inout [FieldError]) {
    if value.street == nil { errors.append(FieldError("\(path).street", "is required")) }
    if value.zipCode == nil { errors.append(FieldError("\(path).zip code", "is required")) }
    if let held = value.location {
        checkCustomerAddressLocation(held, "\(path).location", &errors)
    }
}

/// What a Customer.Address.Location does not follow of its rules, each with the path of its field.
fileprivate func checkCustomerAddressLocation(_ value: Customer.Address.Location, _ path: String, _ errors: inout [FieldError]) {
    if value.latitude == nil { errors.append(FieldError("\(path).latitude", "is required")) }
    if value.longitude == nil { errors.append(FieldError("\(path).longitude", "is required")) }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: CustomerUpdate) -> Values {
    Values(email: changes.email.given, level: changes.level.given, since: changes.since.given, address: changes.address.given, tags: changes.tags.given)
}

/// The Customer with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: String) async throws -> Customer {
    guard let row = try await uow.customers.findById(id) else {
        throw DomainError.notFound(entity: "Customer", key: "\(id)")
    }
    return row
}

/// The Customer as services return it.
fileprivate func read(_ entity: Customer) -> CustomerRead {
    CustomerRead(id: entity.id!, email: entity.email!, level: entity.level, since: entity.since!, address: entity.address!, tags: entity.tags)
}

