/// Conversions between the application models and the "shipments" table: what the service takes and returns.
public enum ShipmentConversions {
    /// A Shipment as the shipments table takes it.
    public static func shipmentModelToShipmentCreate(_ model: ApplicationModels.Shipment) -> ShipmentCreate {
        return ShipmentCreate(
            parcel: shipmentParcelToDocument(model.parcel)
            // TODO: stops: DB2CRUD does not write this conversion (stops)
        )
    }

    /// A row of the shipments table as a Shipment.
    public static func shipmentReadToShipmentModel(_ row: ShipmentRead) -> ApplicationModels.Shipment {
        return ApplicationModels.Shipment(
            id: row.id,
            parcel: shipmentParcelFromDocument(row.parcel),
            stops: { () -> [String] in fatalError("stops: DB2CRUD does not write this conversion (stops)") }()
        )
    }

    /// A Parcel as the documents of the shipments collection keep it.
    private static func shipmentParcelToDocument(_ value: Parcel) -> Shipment.Parcel {
        // Not stored: fragile
        return Shipment.Parcel(
            weight: value.weight
            // TODO: contents: no field of the model gives it (contents)
            // TODO: size: DB2CRUD does not write this conversion (size)
        )
    }

    /// A document of the shipments collection as a Parcel.
    private static func shipmentParcelFromDocument(_ value: Shipment.Parcel) -> Parcel {
        return Parcel(
            weight: value.weight!,
            size: { () -> String in fatalError("size: DB2CRUD does not write this conversion (size)") }(),
            fragile: { () -> Bool in fatalError("fragile: no field of the model gives it (fragile)") }()
        )
    }
}

