/// Operations on shipments. Repositories commit every write.
public struct ShipmentService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Shipment after checking it.
    @discardableResult
    public func createShipment(_ data: ShipmentCreate) async throws -> ShipmentRead {
        let values = Values(parcel: data.parcel.map(Optional.some), stops: data.stops.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Shipment()
            applyValues(&entity, values)
            return try await read(uow.shipments.insert(entity))
        }
    }

    /// The Shipment with this key; notFound when there is none.
    public func getShipment(_ id: String) async throws -> ShipmentRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of shipments, by primary key.
    public func listShipments(offset: Int, limit: Int) async throws -> Page<ShipmentRead> {
        try await unitOfWork.shipments.list(offset: offset, limit: limit).map(read)
    }

    /// Changes the given values of a Shipment.
    @discardableResult
    public func updateShipment(_ id: String, _ changes: ShipmentUpdate) async throws -> ShipmentRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.shipments.update(current))
        }
    }

    /// Deletes a Shipment.
    public func deleteShipment(_ id: String) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.shipments.delete(current)
        }
    }

    /// Adds an item to stops.
    @discardableResult
    public func addStop(_ id: String, _ stop: Shipment.Stop) async throws -> ShipmentRead {
        var errors: [FieldError] = []
        checkShipmentStop(stop, "stops", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Shipment", errors: errors) }
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.shipments.addStop(id, stop) else {
                throw DomainError.notFound(entity: "Shipment", key: "\(id)")
            }
            return read(changed)
        }
    }

    /// Removes an item from stops, by its position.
    @discardableResult
    public func removeStop(_ id: String, _ position: Int) async throws -> ShipmentRead {
        return try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            if !(current.stops ?? []).indices.contains(position) {
                throw DomainError.notFound(entity: "Stop", key: "\(position)")
            }
            guard let changed = try await uow.shipments.removeStop(id, position, (current.stops ?? []).count) else {
                throw DomainError.conflict(entity: "Shipment", reason: "was changed by someone else since it was read", fields: ["stops"])
            }
            return read(changed)
        }
    }
}

